mapper.select:
select bpdr.bill_pay_record_id as billPayRecordId, bpdr.id as billPayDetailRecordId, bpdr.account_item_id as accountItemId, bpdr.amount as amount, bpdr.remark from bill_pay_detail_record bpdr
and bpdr.inservice = #{inservice}
and bpdr.bill_pay_record_id = #{billPayRecordId}
order by bpdr.id desc

select bpdr.bill_pay_record_id as billPayRecordId, bpdr.id as billPayDetailRecordId, bpdr.account_item_id as accountItemId, bpdr.amount as amount, bpdr.remark from bill_pay_detail_record bpdr
and bpdr.inservice = #{inservice}
and bpdr.id = #{id}

select sum(t.amount) from bill_pay_detail_record t


        and DATE_FORMAT(t.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{query.startDate},'%Y-%m-%d')


        and DATE_FORMAT(t.crt_time,'%Y-%m-%d') <= DATE_FORMAT(#{query.endDate},'%Y-%m-%d')


        and t.org_id = #{query.orgId}


        and t.account_item_id = #{query.payId}

SELECT IFNULL( SUM( odpr.actual_receivable + odpr.coupon_workload ), 0 ) AS workloadAmountCompleted FROM ( SELECT odpr.actual_receivable, odpr.coupon_workload, od.executor_id FROM order_detail_pay_record odpr LEFT JOIN order_detail od ON odpr.order_detail_id = od.id
AND odpr.inservice = 1
AND DATE_FORMAT(odpr.crt_time, '%Y-%m') >= #{query.startDate}
AND DATE_FORMAT(odpr.crt_time, '%Y-%m') <= #{query.endDate}
AND odpr.org_id = #{query.orgId}
) odpr WHERE odpr.executor_id IS NOT NULL

select IFNULL(sum(amount),0) from bill_pay_detail_record where bill_pay_record_id in
#{item}
and account_item_id in (23, 26) and inservice = 0

SELECT
    bpdr.order_record_id AS orderRecordId,
    IFNULL(sum(bpdr.amount),0) AS totalAmount
FROM bill_pay_detail_record bpdr
INNER JOIN bill_pay_record bpr ON bpr.id = bpdr.bill_pay_record_id
INNER JOIN bill_record br ON br.id = bpr.bill_record_id

    date_format(bpdr.crt_time, '%Y-%m') = #{query.queryDate}
    AND bpdr.account_item_id in (23, 26)

        and bpdr.inservice = #{inservice}


        AND bpdr.bill_pay_record_id in

            #{item}



        AND br.org_id IN

            #{item}



        AND date_format(bpr.crt_time, '%Y-%m') = #{query.queryDate}
        AND date_format(br.crt_time, '%Y-%m') = #{query.queryDate}


GROUP by bpdr.order_record_id
